{
  "name": "SPIDR连接的Timepix/Medipix像素探测器",
  "name_en": "SPIDR-Connected Timepix/Medipix Pixel Detector",
  "manufacturer": "",
  "description": "通过SPIDR读出系统连接的Timepix/Medipix像素探测器设备，用于配置像素矩阵、DAC、测试脉冲、时序和网络读出参数，服务于粒子、辐射或高速成像实验的数据采集。",
  "description_en": "A Timepix/Medipix pixel detector connected through the SPIDR readout system, used to configure the pixel matrix, DACs, test pulses, timing, and network readout parameters for data acquisition in particle, radiation, or fast imaging experiments.",
  "actions": [
    {
      "action_name": "auto-clearPixelConfig",
      "description": "清除像素配置。",
      "description_en": "Clear the pixel configuration."
    },
    {
      "action_name": "auto-setHeaderFilter",
      "description": "设置数据包头过滤掩码。",
      "description_en": "Set the packet header filter masks."
    },
    {
      "action_name": "auto-reset",
      "description": "复位探测器设备。",
      "description_en": "Reset the detector device."
    },
    {
      "action_name": "auto-reinitDevice",
      "description": "重新初始化探测器设备。",
      "description_en": "Reinitialize the detector device."
    },
    {
      "action_name": "auto-setSenseDac",
      "description": "设置Sense DAC代码。",
      "description_en": "Set the sense DAC code."
    },
    {
      "action_name": "auto-setExternalDac",
      "description": "设置外部DAC代码和值。",
      "description_en": "Set the external DAC code and value."
    },
    {
      "action_name": "auto-getDac",
      "description": "读取DAC设置。",
      "description_en": "Get a DAC setting."
    },
    {
      "action_name": "auto-setDac",
      "description": "设置DAC值。",
      "description_en": "Set a DAC value."
    },
    {
      "action_name": "auto-setDacDefault",
      "description": "恢复默认DAC设置。",
      "description_en": "Restore default DAC settings."
    },
    {
      "action_name": "auto-genConfig",
      "description": "获取/设置通用配置。",
      "description_en": "Get/set the general configuration."
    },
    {
      "action_name": "auto-pllConfig",
      "description": "获取/设置PLL配置。",
      "description_en": "Get/set the PLL configuration."
    },
    {
      "action_name": "auto-outBlockConfig",
      "description": "获取/设置输出块配置。",
      "description_en": "Get/set the output block configuration."
    },
    {
      "action_name": "auto-setOutputMask",
      "description": "设置输出掩码。",
      "description_en": "Set the output mask."
    },
    {
      "action_name": "auto-readoutSpeed",
      "description": "获取/设置读出速度。",
      "description_en": "Get/set the readout speed."
    },
    {
      "action_name": "auto-slaveConfig",
      "description": "获取/设置从设备配置。",
      "description_en": "Get/set the slave configuration."
    },
    {
      "action_name": "auto-powerPulseConfig",
      "description": "获取/设置电源脉冲配置。",
      "description_en": "Get/set the power pulse configuration."
    },
    {
      "action_name": "auto-uploadPacket",
      "description": "上传配置数据包到设备。",
      "description_en": "Upload a configuration packet to the device."
    },
    {
      "action_name": "auto-setTpPeriodPhase",
      "description": "设置测试脉冲周期和相位。",
      "description_en": "Set the test-pulse period and phase."
    },
    {
      "action_name": "auto-tpNumber",
      "description": "获取/设置测试脉冲数量。",
      "description_en": "Get/set the number of test pulses."
    },
    {
      "action_name": "auto-columnTestPulseRegister",
      "description": "获取/设置列测试脉冲寄存器。",
      "description_en": "Get/set the column test-pulse register."
    },
    {
      "action_name": "auto-getPixelConfig",
      "description": "读取像素配置。",
      "description_en": "Get the pixel configuration."
    },
    {
      "action_name": "auto-resetPixels",
      "description": "重置像素阵列设置。",
      "description_en": "Reset the pixel array settings."
    },
    {
      "action_name": "auto-resetPixelConfig",
      "description": "重置像素配置缓冲。",
      "description_en": "Reset the pixel configuration buffer."
    },
    {
      "action_name": "auto-setSinglePixelThreshold",
      "description": "设置单个像素阈值。",
      "description_en": "Set the threshold for a single pixel."
    },
    {
      "action_name": "auto-setPixelThreshold",
      "description": "设置全部像素阈值。",
      "description_en": "Set the threshold for all pixels."
    },
    {
      "action_name": "auto-setSinglePixelMask",
      "description": "设置单个像素掩码。",
      "description_en": "Set the mask for a single pixel."
    },
    {
      "action_name": "auto-setPixelMask",
      "description": "设置全部像素掩码。",
      "description_en": "Set the mask for all pixels."
    },
    {
      "action_name": "auto-setSinglePixelTestBit",
      "description": "设置单个像素测试位。",
      "description_en": "Set the test bit for a single pixel."
    },
    {
      "action_name": "auto-setPixelTestBit",
      "description": "设置全部像素测试位。",
      "description_en": "Set the test bit for all pixels."
    },
    {
      "action_name": "auto-uploadPixelConfig",
      "description": "将像素配置上传到设备。",
      "description_en": "Upload the pixel configuration to the device."
    },
    {
      "action_name": "auto-timer",
      "description": "获取/设置定时器值。",
      "description_en": "Get/set the timer value."
    },
    {
      "action_name": "auto-t0Sync",
      "description": "同步T0时基。",
      "description_en": "Synchronize the T0 timing reference."
    },
    {
      "action_name": "auto-getDacOut",
      "description": "读取DAC输出采样值。",
      "description_en": "Read DAC output samples."
    },
    {
      "action_name": "auto-ipAddrSrc",
      "description": "获取/设置源IP地址。",
      "description_en": "Get/set the source IP address."
    },
    {
      "action_name": "auto-ipAddrDest",
      "description": "获取/设置目标IP地址。",
      "description_en": "Get/set the destination IP address."
    },
    {
      "action_name": "auto-serverPort",
      "description": "获取/设置服务器端口。",
      "description_en": "Get/set the server port."
    }
  ],
  "tag_hints": [
    "Timepix3 pixel detector",
    "Medipix detector control",
    "SPIDR readout",
    "pixel matrix configuration",
    "DAC bias control",
    "test pulse injection",
    "high-speed detector readout"
  ]
}

